import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_boolean_function(n):
        return [random.choice([0, 1]) for _ in range(2**n)]

    def matrix_mult(A, B, mod):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
                    C[i][j] %= mod
        return C

    def matrix_det(A, mod):
        n = len(A)
        det = 1
        for i in range(n):
            pivot = A[i][i]
            if pivot == 0:
                for j in range(i+1, n):
                    if A[j][i] != 0:
                        A[i], A[j] = A[j], A[i]
                        det *= -1
                        break
                else:
                    return 0
            pivot = A[i][i]
            for j in range(n):
                A[i][j] = (A[i][j] * pow(pivot, mod-2, mod)) % mod
            for j in range(n):
                if i != j:
                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] = (A[j][k] - factor * A[i][k]) % mod
        return det

    def symplectic_hull_volume(f, n):
        F = [f[i:i+n] for i in range(0, len(f), n)]
        A = [[sum(F[i][j] * F[k][j] for j in range(n)) for k in range(n)] for i in range(n)]
        return abs(matrix_det(A, 2))

    def communication_complexity_rank_variance(f):
        n = int(math.log2(len(f)))
        rank = sum(1 for x in f if x == 1)
        return (rank - n/2)**2

    results = []
    for n in [5, 10, 15, 20, 30, 40]:
        instances_tested = 0
        shv_sum = 0
        crv_sum = 0
