    mean_crv = sum(crv_values) / len(crv_values)
    correlation_coefficient = sum((shv_values[i] - mean_shv) * (crv_values[i] - mean_crv) for i in range(len(shv_values))) / (len(shv_values) * math.sqrt(sum((shv_values[i] - mean_shv)**2 for i in range(len(shv_values)))) * math.sqrt(sum((crv_values[i] - mean_crv)**2 for i in range(len(crv_values))))))

    return {
